import {
  TagsInput as TagsInputPrimitive,
  useTagsInput,
  useTagsInputContext,
  useTagsInputItemContext,
} from '@ark-ui/solid/tags-input';
import { children, For, splitProps } from 'solid-js';
import type { ComponentProps } from 'solid-js';
import { cn } from '@/lib/moduix/cn';
import { CloseIcon } from '@/lib/moduix/icons/ui/Icons';
import { CloseButton } from '../close-button';

function TagsInputRoot(props: ComponentProps<typeof TagsInputPrimitive.Root>) {
  const [local, others] = splitProps(props, ['asChild', 'children', 'class']);

  return (
    <TagsInputPrimitive.Root
      asChild={local.asChild}
      data-slot="tags-input-root"
      class={cn(
        'flex w-full max-w-96 flex-col gap-1 text-foreground data-disabled:opacity-50',
        local.class,
      )}
      {...others}
    >
      {local.children}
    </TagsInputPrimitive.Root>
  );
}

function TagsInputRootProvider(props: ComponentProps<typeof TagsInputPrimitive.RootProvider>) {
  const [local, others] = splitProps(props, ['asChild', 'children', 'class']);

  return (
    <TagsInputPrimitive.RootProvider
      asChild={local.asChild}
      data-slot="tags-input-root-provider"
      class={cn(
        'flex w-full max-w-96 flex-col gap-1 text-foreground data-disabled:opacity-50',
        local.class,
      )}
      {...others}
    >
      {local.children}
    </TagsInputPrimitive.RootProvider>
  );
}

function TagsInputLabel(props: ComponentProps<typeof TagsInputPrimitive.Label>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <TagsInputPrimitive.Label
      data-slot="tags-input-label"
      class={cn(
        'inline-flex items-center gap-1 text-sm leading-5 font-medium text-foreground data-disabled:opacity-50',
        local.class,
      )}
      {...others}
    />
  );
}

function TagsInputControl(props: ComponentProps<typeof TagsInputPrimitive.Control>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <TagsInputPrimitive.Control
      data-slot="tags-input-control"
      class={cn(
        'flex min-h-control-md w-full flex-wrap items-center gap-1 rounded-md border border-border bg-background px-2 py-[0.3125rem] text-foreground outline-1 -outline-offset-1 outline-transparent transition-[border-color,outline-color,background-color,opacity] duration-200 ease-in-out data-focus:outline-ring data-invalid:border-destructive data-invalid:data-focus:outline-destructive data-readonly:bg-background data-readonly:text-foreground data-disabled:pointer-events-none motion-reduce:transition-none',
        local.class,
      )}
      {...others}
    />
  );
}

function TagsInputItem(props: ComponentProps<typeof TagsInputPrimitive.Item>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <TagsInputPrimitive.Item
      data-slot="tags-input-item"
      class={cn('contents', local.class)}
      {...others}
    />
  );
}

function TagsInputItemPreview(props: ComponentProps<typeof TagsInputPrimitive.ItemPreview>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <TagsInputPrimitive.ItemPreview
      data-slot="tags-input-item-preview"
      class={cn(
        'inline-flex min-h-control-xs min-w-0 max-w-full items-center gap-1 rounded-full border border-transparent bg-secondary px-2 py-0.5 text-xs leading-4 font-medium text-secondary-foreground transition-[border-color,background-color,color,box-shadow] duration-200 ease-in-out data-highlighted:ring-1 data-highlighted:ring-ring data-disabled:opacity-50 motion-reduce:transition-none',
        local.class,
      )}
      {...others}
    />
  );
}

function TagsInputItemText(props: ComponentProps<typeof TagsInputPrimitive.ItemText>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <TagsInputPrimitive.ItemText
      data-slot="tags-input-item-text"
      class={cn('min-w-0 truncate', local.class)}
      {...others}
    />
  );
}

function TagsInputItemDeleteTrigger(
  props: ComponentProps<typeof TagsInputPrimitive.ItemDeleteTrigger>,
) {
  const [local, others] = splitProps(props, ['children', 'class']);
  const resolvedChildren = children(() => local.children);

  return (
    <TagsInputPrimitive.ItemDeleteTrigger
      data-slot="tags-input-item-delete-trigger"
      class={cn(
        'inline-flex size-4 shrink-0 cursor-pointer items-center justify-center rounded-full border-0 bg-transparent p-0 text-inherit outline-0 transition-[background-color,color,opacity,box-shadow] duration-200 ease-in-out focus-visible:ring-1 focus-visible:ring-ring data-disabled:pointer-events-none data-disabled:cursor-default data-disabled:opacity-50 disabled:pointer-events-none disabled:cursor-default disabled:opacity-50 motion-reduce:transition-none [&>svg]:pointer-events-none [&>svg]:size-2.5 [&>svg]:shrink-0 [@media(hover:hover)]:hover:bg-current/10',
        local.class,
      )}
      {...others}
    >
      {resolvedChildren() ?? <CloseIcon />}
    </TagsInputPrimitive.ItemDeleteTrigger>
  );
}

function TagsInputItemInput(props: ComponentProps<typeof TagsInputPrimitive.ItemInput>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <TagsInputPrimitive.ItemInput
      data-slot="tags-input-item-input"
      class={cn(
        'h-control-xs min-w-28 grow-0 shrink basis-28 border-0 bg-transparent px-1 text-sm leading-5 text-inherit outline-0 placeholder:text-muted-foreground read-only:cursor-default data-readonly:cursor-default [font:inherit]',
        local.class,
      )}
      {...others}
    />
  );
}

function TagsInputInput(props: ComponentProps<typeof TagsInputPrimitive.Input>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <TagsInputPrimitive.Input
      data-slot="tags-input-input"
      class={cn(
        'h-control-xs min-w-28 grow shrink basis-28 border-0 bg-transparent px-1 text-sm leading-5 text-inherit outline-0 placeholder:text-muted-foreground read-only:cursor-default data-readonly:cursor-default data-readonly:hidden [font:inherit]',
        local.class,
      )}
      {...others}
    />
  );
}

function TagsInputClearTrigger(props: ComponentProps<typeof TagsInputPrimitive.ClearTrigger>) {
  const [local, others] = splitProps(props, [
    'aria-label',
    'aria-labelledby',
    'asChild',
    'children',
    'class',
  ]);
  const tagsInput = useTagsInputContext();
  const resolvedChildren = children(() => local.children);
  const clearTriggerLabel = () => tagsInput().getClearTriggerProps()['aria-label'];

  if (local.asChild) {
    return (
      <TagsInputPrimitive.ClearTrigger
        asChild={local.asChild}
        data-slot="tags-input-clear-trigger"
        class={cn(
          'size-control-xs ms-auto shrink-0 self-center rounded-sm bg-transparent text-muted-foreground transition-[background-color,color,opacity] duration-200 ease-in-out focus-visible:outline-1 focus-visible:outline-offset-1 focus-visible:outline-ring data-readonly:hidden motion-reduce:transition-none [&>svg]:size-3 [@media(hover:hover)]:hover:bg-muted [@media(hover:hover)]:hover:text-foreground',
          local.class,
        )}
        aria-label={local['aria-label']}
        aria-labelledby={local['aria-labelledby']}
        {...others}
      >
        {local.children}
      </TagsInputPrimitive.ClearTrigger>
    );
  }

  return (
    <TagsInputPrimitive.ClearTrigger
      asChild={(triggerProps) => (
        <CloseButton.Root
          {...triggerProps()}
          aria-label={local['aria-label'] ?? clearTriggerLabel()}
          aria-labelledby={local['aria-labelledby']}
          data-part="clear-trigger"
          data-scope="tags-input"
          data-slot="tags-input-clear-trigger"
        >
          {resolvedChildren()}
        </CloseButton.Root>
      )}
      data-slot="tags-input-clear-trigger"
      class={cn(
          'size-control-xs ms-auto shrink-0 self-center rounded-sm bg-transparent text-muted-foreground transition-[background-color,color,opacity] duration-200 ease-in-out focus-visible:outline-1 focus-visible:outline-offset-1 focus-visible:outline-ring data-readonly:hidden motion-reduce:transition-none [&>svg]:size-3 [@media(hover:hover)]:hover:bg-muted [@media(hover:hover)]:hover:text-foreground',
        local.class,
      )}
      {...others}
    />
  );
}

const TagsInputContext = TagsInputPrimitive.Context;

function TagsInputItems() {
  return (
    <TagsInputContext>
      {(tagsInput) => (
        <For each={tagsInput().value}>
          {(value, index) => (
            <TagsInputItem index={index()} value={value}>
              <TagsInputItemPreview>
                <TagsInputItemText>{value}</TagsInputItemText>
                <TagsInputItemDeleteTrigger />
              </TagsInputItemPreview>
              <TagsInputItemInput />
            </TagsInputItem>
          )}
        </For>
      )}
    </TagsInputContext>
  );
}

const TagsInput = Object.assign(TagsInputRoot, {
  Root: TagsInputRoot,
  RootProvider: TagsInputRootProvider,
  HiddenInput: TagsInputPrimitive.HiddenInput,
  Label: TagsInputLabel,
  Control: TagsInputControl,
  Item: TagsInputItem,
  ItemContext: TagsInputPrimitive.ItemContext,
  ItemPreview: TagsInputItemPreview,
  ItemText: TagsInputItemText,
  ItemDeleteTrigger: TagsInputItemDeleteTrigger,
  ItemInput: TagsInputItemInput,
  Input: TagsInputInput,
  ClearTrigger: TagsInputClearTrigger,
  Context: TagsInputContext,
  Items: TagsInputItems,
});

export { TagsInput, useTagsInput, useTagsInputContext, useTagsInputItemContext };

export {
  TagsInput,
  useTagsInput,
  useTagsInputContext,
  useTagsInputItemContext,
} from './TagsInput.js';
